from pathlib import Path
import json
import re

demo=Path(__file__).resolve().parents[1]/'02_Prediccion_y_escenarios_de_riesgo/demo'
html=(demo/'demo7.html').read_text(encoding='utf-8')
if 'id="d7-action-editor"' in html:
    raise SystemExit('La interfaz de planeación ya está integrada. Usa tools/construir_demo7.py para reconstruir recursos.')
html=html.replace('v=7-impact','v=7-planning')
html=html.replace('<div class="hero-actions">','<div class="hero-actions"><button class="button d7-tour-start" id="d7-start-tour" type="button">Recorrido para presentar</button>',1)
html=html.replace('<h3 id="d6-state-plan-title">Plan de acción estatal</h3>','<div class="d7-block-heading"><h3 id="d6-state-plan-title">Plan de acción estatal</h3><div class="d7-export-actions"><button type="button" id="d7-download-brief" disabled>Descargar ficha</button><button type="button" id="d7-print-brief" disabled>Imprimir / guardar PDF</button></div></div><div id="d7-diagnosis" class="d7-diagnosis" hidden></div>',1)
editor='''<section id="d7-action-editor" class="d7-planning-box" aria-labelledby="d7-editor-title" hidden><h4 id="d7-editor-title">Supuestos de cada acción del plan</h4><p class="d6-note">Selecciona una actividad, define personas alcanzadas y ajusta el efecto supuesto entre quienes reciben la acción. Se calcula una actividad a la vez; sus efectos no se suman.</p><label for="d7-plan-action">Actividad del plan estatal</label><select id="d7-plan-action"></select><p id="d7-action-assumption" class="d6-note"></p><div class="d7-editor-grid"><label>Personas alcanzadas<input id="d7-action-reach" type="number" min="0" step="1" inputmode="numeric"></label><label>Efecto central (pp)<input id="d7-action-effect" type="number" min="0" max="100" step="0.01"></label><label>Límite inferior (pp)<input id="d7-action-low" type="number" min="0" max="100" step="0.01"></label><label>Límite superior (pp)<input id="d7-action-high" type="number" min="0" max="100" step="0.01"></label><label>Distribución<select id="d7-action-distribution"><option value="proporcional">Proporcional a la base observable</option><option value="prioridad">Primero los municipios prioritarios</option></select></label><label>Criterio de prioridad<select id="d7-action-lens"><option value="tasa">Mayor porcentaje de abstención</option><option value="volumen">Mayor volumen de abstención</option><option value="deterioro">Mayor deterioro frente a 2021</option></select></label></div><p id="d7-editor-error" class="d7-error" role="status"></p><p id="d7-editor-mode" class="d6-note"></p><button type="button" id="d7-use-state-action">Aplicar estos supuestos al cálculo estatal</button><a href="../../docs/PLANES_ACCION_ESTATALES_PARTICIPACION.md" target="_blank" rel="noopener noreferrer">Fuente de las actividades ↗</a></section>'''
allocation='''<section id="d7-allocation" class="d7-planning-box" aria-labelledby="d7-allocation-title" hidden><h4 id="d7-allocation-title">¿Cómo se distribuyen los recursos?</h4><p id="d7-allocation-summary"></p><div class="d7-allocation-filters"><label>Mostrar<select id="d7-allocation-filter"><option value="todos">Todos los municipios</option><option value="atendidos">Con atención asignada</option><option value="pendientes">Pendientes de atención</option><option value="sin_datos">Sin estimación</option></select></label><button id="d7-allocation-download" type="button">Descargar distribución CSV</button></div><p class="d6-note">Recurso mostrado: personas que se supone alcanzar. No representa presupuesto monetario ni capacidad confirmada. La prioridad depende del criterio elegido.</p><div class="table-wrap d7-allocation-scroll"><table><thead><tr><th>Prioridad</th><th>Municipio</th><th>Estado de atención</th><th>Personas asignadas</th><th>Abstención base</th><th>Reducción (pp)</th><th>Criterio</th></tr></thead><tbody id="d7-allocation-rows"></tbody></table></div><div class="d7-pagination"><button type="button" id="d7-allocation-prev">Anterior</button><span id="d7-allocation-page" aria-live="polite"></span><button type="button" id="d7-allocation-next">Siguiente</button></div></section>'''
match=re.search(r'<section class="d7-map-comparison".*?</section>',html,re.S)
if not match:raise ValueError('Comparison map section not found')
maps=match.group(0)
html=html[:match.start()]+html[match.end():]
maps=maps.replace('<div class="d7-map-grid">','<label class="d7-map-view-label" for="d7-map-view">Visualización<select id="d7-map-view"><option value="paired">Sin y con intervención</option><option value="difference">Solo diferencias (pp)</option></select></label><div class="d7-map-grid" id="d7-paired-maps">')
maps=maps.replace('<div id="d7-map-legend"','<article id="d7-difference-wrap" hidden><h4>Reducción hipotética de la abstención</h4><div id="d7-map-difference" class="d7-map" role="region" aria-label="Mapa de diferencias de abstención en puntos porcentuales"></div></article><div id="d7-map-legend"')
maps=maps.replace('class="d7-map-comparison"','class="d7-map-comparison" id="d7-comparison-block" hidden',1)
html=html.replace('<section class="intervention" id="paso-3">',editor+allocation+maps+'<section class="intervention" id="paso-3">',1)
dialog='''<dialog id="d7-tour" aria-labelledby="d7-tour-title"><div class="d7-tour-heading"><span id="d7-tour-counter"></span><button type="button" id="d7-tour-close" aria-label="Cerrar recorrido">×</button></div><h3 id="d7-tour-title"></h3><p id="d7-tour-text"></p><div class="d7-tour-buttons"><button type="button" id="d7-tour-prev">Anterior</button><button type="button" id="d7-tour-next">Siguiente</button></div></dialog>'''
html=html.replace('</body>',dialog+'</body>')
(demo/'demo7.html').write_text(html,encoding='utf-8')
config=json.loads((demo/'build.demo7.config.json').read_text(encoding='utf-8'))
if 'src/demo7/planning.js' not in config['scripts']:config['scripts'].insert(-1,'src/demo7/planning.js')
(demo/'build.demo7.config.json').write_text(json.dumps(config,indent=2)+'\n',encoding='utf-8')
print('Planning, allocation, export and presentation interfaces added.')
